class Counter {
    private int value;

    public Counter(int value) { this.value = value; }
    public void increment() { this.value = this.value + 1; }
    public readonly int getValue() { return this.value; }
}

void incrementTwice(borrow mut Counter counter) {
    counter.increment();
    counter.increment();
}

int read(borrow Counter counter) {
    return counter.getValue();
}

public class Main {
    public static void main() {
        Counter counter = new Counter(40);
        incrementTwice(counter); // Emprunt pour l'appel, pas un transfert.
        println(read(counter));

        {
            borrow Counter first = counter;
            borrow Counter second = counter;
            println(first.getValue() + second.getValue());
        } // Les deux emprunts partages se terminent ici.

        {
            borrow mut Counter editor = counter;
            editor.increment();
        } // L'emprunt exclusif se termine ici.

        println(counter.getValue());
    }
}

class Counter {
    int value = 0;
    void increment() { value = value + 1; }
    readonly int getValue() { return value; }
}
void main() {
    Counter counter = new Counter();
    {
        borrow mut Counter editor = counter;
        editor.increment();
        {
            borrow Counter reader = editor;
            println(reader.getValue());
            // editor.increment() serait refuse tant que reader existe.
        }
        editor.increment();
        println(editor.getValue());
    }
    println(counter.getValue());
}

class Counter {
    private int value;
    Counter(int value) { this.value = value; }
    void increment() { this.value = this.value + 1; }
    readonly int getValue() { return this.value; }
}

// Classe a champ emprunte : vue locale, non transferable hors de son bloc.
class CounterView {
    private borrow Counter target;
    private String title;

    CounterView(borrow Counter target, String title) {
        this.target = target;
        this.title = title;
    }
    readonly void display() {
        println(this.title);
        println(this.target.getValue());
    }
}

void main() {
    Counter counter = new Counter(42);
    {
        CounterView view = new CounterView(counter, "Compteur partage");
        view.display();
        // counter.increment() serait refuse pendant la vie de view.
    } // Detruit view, mais pas l'objet qu'elle emprunte.
    counter.increment();
    println(counter.getValue());
}

class Counter {
    int value = 0;
    void add(int amount) { value = value + amount; }
    readonly int getValue() { return value; }
}
void main() {
    Counter counter = new Counter();
    int i = 0;
    while (i < 5) {
        borrow mut Counter editor = counter;
        i = i + 1;
        if (i == 2) { continue; }
        if (i == 5) { break; }
        editor.add(i);
    }
    println(counter.getValue());
}

class Engine {
    int power = 120;
    readonly int getPower() { return power; }
    void tune() { power = power + 10; }
}
class Car {
    Engine engine = new Engine();
    readonly int getPower() { return engine.getPower(); }
    void tune() { engine.tune(); }
}
void show(borrow Car car) { println(car.getPower()); }
void main() {
    Car car = new Car();
    show(car);
    car.tune();
    show(car);
}
